<script setup lang="ts">import{apiErrorMessage}from'~/utils/api-error';useHead({title:'Activer votre compte'});const route=useRoute();const token=computed(()=>typeof route.query.token==='string'?route.query.token:'');const password=ref('');const confirmation=ref('');const pending=ref(false);const done=ref(false);const errorMessage=ref('');async function submit(){if(password.value!==confirmation.value){errorMessage.value='Les deux mots de passe ne correspondent pas.';return}pending.value=true;errorMessage.value='';try{await $fetch('/api/auth/activate',{method:'POST',body:{token:token.value,password:password.value}});done.value=true}catch(error){errorMessage.value=apiErrorMessage(error,'Le lien d’activation est invalide ou expiré.')}finally{pending.value=false}}</script>
<template><section class="section"><div class="container auth-narrow"><div v-if="!token" class="alert alert-error">Invitation incomplète.</div><div v-else-if="done" class="card card-pad"><p class="eyebrow">Compte activé</p><h1>Bienvenue dans l’espace IFICS.</h1><p>Vous pouvez maintenant vous connecter. Si votre rôle impose le MFA, sa configuration vous sera demandée immédiatement.</p><NuxtLink to="/login" class="btn btn-primary">Continuer</NuxtLink></div><form v-else class="card card-pad" @submit.prevent="submit"><p class="eyebrow">Invitation IFICS</p><h1>Choisir votre mot de passe</h1><p class="muted">Le lien est à usage unique et expire après sept jours.</p><div v-if="errorMessage" class="alert alert-error" role="alert">{{errorMessage}}</div><div class="field"><label for="activation-password">Mot de passe</label><input id="activation-password" v-model="password" class="input" type="password" minlength="12" autocomplete="new-password" required></div><div class="field"><label for="activation-confirm">Confirmation</label><input id="activation-confirm" v-model="confirmation" class="input" type="password" minlength="12" autocomplete="new-password" required></div><button class="btn btn-primary" type="submit" :disabled="pending">{{pending?'Activation…':'Activer mon compte'}}</button></form></div></section></template>
<style scoped>.auth-narrow{max-width:560px}.card{display:flex;flex-direction:column;gap:16px}.card h1,.card p{margin:0}</style>
